// Define TypeScript interfaces
interface OrderItem {
  id: number;
  name: string;
  price: number;
  quantity: number;
  image: string;
  seller: string;
}

interface TimelineStep {
  status: string;
  date: string;
  completed: boolean;
}

interface Order {
  id: string;
  date: string;
  status: "delivered" | "shipped" | "processing" | "cancelled" | "returned";
  total: number;
  items: OrderItem[];
  shipping: {
    address: string;
    method: string;
    trackingId: string;
  };
  payment: {
    method: string;
    transactionId: string;
  };
  timeline: TimelineStep[];
}

